import { db } from '../../db'
import { productCache } from '../../cache/productCache'

// 管理画面の価格更新。監査ログも残す。
export async function updatePrice(productId: number, priceYen: number, actorId: string) {
  await db.tx(async (t) => {
    await t.none('UPDATE products SET price_yen = $1, updated_at = now() WHERE id = $2', [priceYen, productId])
    await t.none('INSERT INTO audit_log (actor_id, action, target) VALUES ($1, $2, $3)', [actorId, 'price.update', `product:${productId}`])
  })
  await productCache.invalidate(productId)
}

import { redis } from './redis'

const TTL_SECONDS = 3600

function key(productId: number, locale: string) {
  return `product:${productId}:${locale}`
}

export const productCache = {
  async get(productId: number, locale: string) {
    const hit = await redis.get(key(productId, locale))
    return hit ? JSON.parse(hit) : null
  },
  async set(productId: number, locale: string, value: unknown) {
    await redis.set(key(productId, locale), JSON.stringify(value), 'EX', TTL_SECONDS)
  },
  async invalidate(productId: number) {
    await redis.del(`product:${productId}`)
  },
}

